import{_ as l,o as e,c as t,a2 as i}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"项目详情模板（复制这个文件）","description":"","frontmatter":{},"headers":[],"relativePath":"projects/template.md","filePath":"projects/template.md","lastUpdated":1794790394000}'),o={name:"projects/template.md"};function r(s,a,c,n,p,d){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="项目详情模板-复制这个文件" tabindex="-1">项目详情模板（复制这个文件） <a class="header-anchor" href="#项目详情模板-复制这个文件" aria-label="Permalink to &quot;项目详情模板（复制这个文件）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">怎么用</p><p>把本文件复制成 <code>docs/projects/你的项目名.md</code>，然后把下面的内容替换成你的项目。 保留五段结构就行 —— 面试官看学生项目，最想知道的是<strong>你亲手做了什么、卡在哪里、怎么解决的</strong>。</p></div><h2 id="项目背景" tabindex="-1">项目背景 <a class="header-anchor" href="#项目背景" aria-label="Permalink to &quot;项目背景&quot;">​</a></h2><p>【待填写】</p><p>写清楚三件事：这是什么（课程作业 / 自己想做 / 帮别人做的）、为什么做、 当时想解决什么问题。一两句话就够，不要写成产品发布会。</p><h2 id="我做了什么" tabindex="-1">我做了什么 <a class="header-anchor" href="#我做了什么" aria-label="Permalink to &quot;我做了什么&quot;">​</a></h2><p>【待填写】</p><ul><li>负责的部分：例如&quot;首页和列表页的静态还原&quot;、&quot;写了个简单的数据筛选逻辑&quot;</li><li>用到的技术：例如 HTML / CSS / JavaScript / Vue 3 / Git</li><li>项目规模：几个人一起做、做了多久、你在其中是什么角色</li></ul><h2 id="技术方案" tabindex="-1">技术方案 <a class="header-anchor" href="#技术方案" aria-label="Permalink to &quot;技术方案&quot;">​</a></h2><p>【待填写】</p><p>重点写<strong>你的判断</strong>，而不是名词堆砌：</p><ul><li>为什么选这个做法？有没有考虑过另一种？</li><li>页面结构怎么划分的？样式是怎么组织的？</li><li>如果是跟着教程做的，哪部分是你自己改的、自己加的？</li></ul><h2 id="遇到的坑与解决" tabindex="-1">遇到的坑与解决 <a class="header-anchor" href="#遇到的坑与解决" aria-label="Permalink to &quot;遇到的坑与解决&quot;">​</a></h2><p>【待填写】</p><p>这一段最能体现真实水平，写具体一点：</p><ol><li>现象：例如&quot;手机上打开布局全乱了&quot;</li><li>排查：怎么定位到的（开发者工具、看文档、搜报错）</li><li>解决：最后改了什么</li><li>收获：下次会怎么避免</li></ol><h2 id="结果" tabindex="-1">结果 <a class="header-anchor" href="#结果" aria-label="Permalink to &quot;结果&quot;">​</a></h2><p>【待填写】</p><ul><li>完成度：能跑起来的功能有哪些，哪些还没做</li><li>有没有部署上线？地址是什么？</li><li>如果能看到效果，放一张截图：<code>![页面截图](/screenshots/项目名.png)</code></li></ul><h2 id="复盘" tabindex="-1">复盘 <a class="header-anchor" href="#复盘" aria-label="Permalink to &quot;复盘&quot;">​</a></h2><p>【待填写】</p><ul><li>✅ 做对的地方</li><li>🔧 现在回看会怎么改</li><li>📚 通过这个项目学会了什么（这一点对实习生很重要）</li></ul><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><ul class="tags"><li>HTML</li><li>CSS</li><li>JavaScript</li><li>Git</li></ul>',24)])])}const m=l(o,[["render",r]]);export{u as __pageData,m as default};
